def verifier_ip(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num > 255:
            return False
        if len(part) > 1 and part[0] == '0':
            return False
    return True
