def freq_chars(s):
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    return counts

def convertir_octets(n):
    if n >= 1024**3:
        return f"{n / 1024**3:.2f} Go"
    elif n >= 1024**2:
        return f"{n / 1024**2:.2f} Mo"
    elif n >= 1024:
        return f"{n / 1024:.2f} Ko"
    else:
        return f"{n} o"

