def dichotomie(l, x):
    low = 0
    high = len(l) - 1
    while low <= high:
        mid = (low + high) // 2
        if l[mid] == x:
            return mid
        elif x < l[mid]:
            high = mid - 1
        else:
            low = mid + 1
    return -1

def supprimer_doublons(l):
    seen = set()
    result = []
    for elem in l:
        if elem not in seen:
            seen.add(elem)
            result.append(elem)
    return result

import math

def est_premier(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(math.sqrt(n)) + 1
    for i in range(3, max_divisor, 2):
        if n % i == 0:
            return False
    return True
